            continue;
        long hex = ourArmy->getAdjacentHex(ourHex, i);
        if (hex < 0 || hex >= 187)
            continue;
        army* target = g_combatManager->m_cells[hex].getArmy();
        if (target == 0)
            continue;
        if (target->m_combatSide == ourGroup)
            continue;
        if (counted & (1 << target->m_bitIndex))
            continue;
